DO $artifact_object_storage$ BEGIN
 IF to_regclass('public.platform_tenants') IS NULL OR to_regclass('public.platform_users') IS NULL THEN RETURN; END IF;
 CREATE TABLE platform_artifact_objects(id UUID PRIMARY KEY,tenant_id VARCHAR(64) NOT NULL,created_by VARCHAR(36) NOT NULL,content_sha256 VARCHAR(71) NOT NULL,byte_size BIGINT NOT NULL,media_type VARCHAR(160) NOT NULL,storage_reference VARCHAR(320) NOT NULL,encryption_reference VARCHAR(320) NOT NULL,retain_until TIMESTAMPTZ NOT NULL,delete_when_unreferenced BOOLEAN NOT NULL,state VARCHAR(20) NOT NULL,revision BIGINT NOT NULL,created_at TIMESTAMPTZ NOT NULL,updated_at TIMESTAMPTZ NOT NULL,deleted_at TIMESTAMPTZ,CONSTRAINT fk_artifact_object_tenant FOREIGN KEY(tenant_id) REFERENCES platform_tenants(id),CONSTRAINT fk_artifact_object_creator FOREIGN KEY(created_by) REFERENCES platform_users(id),CONSTRAINT uk_artifact_object_scope UNIQUE(id,tenant_id),CONSTRAINT uk_artifact_object_storage UNIQUE(storage_reference),CONSTRAINT uk_artifact_object_content UNIQUE(tenant_id,content_sha256,byte_size,encryption_reference),CONSTRAINT ck_artifact_object_hash CHECK(content_sha256~'^sha256:[0-9a-f]{64}$'),CONSTRAINT ck_artifact_object_refs CHECK(storage_reference~'^artifact-object:[A-Za-z0-9_.:-]{1,300}$' AND encryption_reference~'^tenant-key:[A-Za-z0-9_.:-]{1,300}$'),CONSTRAINT ck_artifact_object_state CHECK(state IN('READY','DELETE_PENDING','BLOCKED','DELETED') AND revision>0 AND byte_size BETWEEN 0 AND 5368709120 AND ((state='DELETED' AND deleted_at IS NOT NULL) OR (state<>'DELETED' AND deleted_at IS NULL))));
 CREATE TABLE platform_artifact_object_staging(id UUID PRIMARY KEY,tenant_id VARCHAR(64) NOT NULL,requested_by VARCHAR(36) NOT NULL,request_id VARCHAR(200) NOT NULL,expected_sha256 VARCHAR(71) NOT NULL,expected_bytes BIGINT NOT NULL,media_type VARCHAR(160) NOT NULL,encryption_reference VARCHAR(320) NOT NULL,staging_reference VARCHAR(320),state VARCHAR(20) NOT NULL,published_object_id UUID,revision BIGINT NOT NULL,expires_at TIMESTAMPTZ NOT NULL,created_at TIMESTAMPTZ NOT NULL,updated_at TIMESTAMPTZ NOT NULL,CONSTRAINT fk_artifact_staging_tenant FOREIGN KEY(tenant_id) REFERENCES platform_tenants(id),CONSTRAINT fk_artifact_staging_actor FOREIGN KEY(requested_by) REFERENCES platform_users(id),CONSTRAINT uk_artifact_staging_request UNIQUE(tenant_id,requested_by,request_id),CONSTRAINT uk_artifact_staging_scope UNIQUE(id,tenant_id),CONSTRAINT ck_artifact_staging_hash CHECK(expected_sha256~'^sha256:[0-9a-f]{64}$'),CONSTRAINT ck_artifact_staging_refs CHECK(encryption_reference~'^tenant-key:[A-Za-z0-9_.:-]{1,300}$' AND (staging_reference IS NULL OR staging_reference~'^artifact-staging:[A-Za-z0-9_.:-]{1,300}$')),CONSTRAINT ck_artifact_staging_state CHECK(state IN('OPEN','VERIFIED','PUBLISHED','REJECTED','UNKNOWN') AND revision>0 AND expected_bytes BETWEEN 0 AND 5368709120 AND ((state='OPEN' AND staging_reference IS NULL) OR (state<>'OPEN' AND staging_reference IS NOT NULL)) AND ((state='PUBLISHED')=(published_object_id IS NOT NULL))));
 ALTER TABLE platform_artifact_object_staging ADD CONSTRAINT fk_artifact_staging_published FOREIGN KEY(published_object_id,tenant_id) REFERENCES platform_artifact_objects(id,tenant_id);
 CREATE TABLE platform_artifact_object_references(id UUID PRIMARY KEY,tenant_id VARCHAR(64) NOT NULL,object_id UUID NOT NULL,owner_type VARCHAR(20) NOT NULL,owner_resource_id VARCHAR(200) NOT NULL,purpose VARCHAR(200) NOT NULL,state VARCHAR(16) NOT NULL,revision BIGINT NOT NULL,created_at TIMESTAMPTZ NOT NULL,released_at TIMESTAMPTZ,CONSTRAINT fk_artifact_reference_object FOREIGN KEY(object_id,tenant_id) REFERENCES platform_artifact_objects(id,tenant_id),CONSTRAINT uk_artifact_reference_owner UNIQUE(object_id,owner_type,owner_resource_id,purpose),CONSTRAINT ck_artifact_reference_state CHECK(owner_type IN('ARTIFACT','PROJECT','KNOWLEDGE') AND state IN('ACTIVE','RELEASED') AND revision>0 AND ((state='RELEASED')=(released_at IS NOT NULL))));
 CREATE TABLE platform_artifact_object_legal_holds(id UUID PRIMARY KEY,tenant_id VARCHAR(64) NOT NULL,object_id UUID NOT NULL,reason_sha256 VARCHAR(71) NOT NULL,placed_by VARCHAR(36) NOT NULL,state VARCHAR(16) NOT NULL,revision BIGINT NOT NULL,placed_at TIMESTAMPTZ NOT NULL,released_by VARCHAR(36),released_at TIMESTAMPTZ,CONSTRAINT fk_artifact_hold_object FOREIGN KEY(object_id,tenant_id) REFERENCES platform_artifact_objects(id,tenant_id),CONSTRAINT fk_artifact_hold_placer FOREIGN KEY(placed_by) REFERENCES platform_users(id),CONSTRAINT fk_artifact_hold_releaser FOREIGN KEY(released_by) REFERENCES platform_users(id),CONSTRAINT ck_artifact_hold_hash CHECK(reason_sha256~'^sha256:[0-9a-f]{64}$'),CONSTRAINT ck_artifact_hold_state CHECK(state IN('ACTIVE','RELEASED') AND revision>0 AND ((state='RELEASED')=(released_by IS NOT NULL AND released_at IS NOT NULL))));
 CREATE UNIQUE INDEX uk_artifact_active_hold ON platform_artifact_object_legal_holds(object_id) WHERE state='ACTIVE';
 CREATE TABLE platform_artifact_object_deletions(id UUID PRIMARY KEY,tenant_id VARCHAR(64) NOT NULL,object_id UUID NOT NULL,state VARCHAR(16) NOT NULL,claim_token UUID,claim_owner VARCHAR(160),lease_until TIMESTAMPTZ,fencing_token BIGINT NOT NULL DEFAULT 0,safe_error_code VARCHAR(120),revision BIGINT NOT NULL,created_at TIMESTAMPTZ NOT NULL,updated_at TIMESTAMPTZ NOT NULL,completed_at TIMESTAMPTZ,CONSTRAINT fk_artifact_deletion_object FOREIGN KEY(object_id,tenant_id) REFERENCES platform_artifact_objects(id,tenant_id),CONSTRAINT uk_artifact_deletion_object UNIQUE(object_id),CONSTRAINT ck_artifact_deletion_state CHECK(state IN('PENDING','CLAIMED','BLOCKED','COMPLETED') AND revision>0 AND fencing_token>=0 AND ((state='CLAIMED')=(claim_token IS NOT NULL AND claim_owner IS NOT NULL AND lease_until IS NOT NULL)) AND ((state='COMPLETED')=(completed_at IS NOT NULL))),CONSTRAINT ck_artifact_deletion_error CHECK(safe_error_code IS NULL OR safe_error_code~'^[A-Z0-9_-]{1,120}$'));
 CREATE INDEX idx_artifact_deletion_due ON platform_artifact_object_deletions(created_at,id) WHERE state='PENDING';
END $artifact_object_storage$;
